    #[test]
    fn build_infers_linux_gnu_abi_from_package_name_suffix_via_npm_role() {
        let dir = tempfile::tempdir().expect("tempdir");
        let root = dir.path();
        std::fs::create_dir_all(root.join("pkg")).unwrap();
        std::fs::write(
            root.join("pkg/package.json"),
