            pattern.matches(&cargo_pkg),
            "'cargo:internal-*' must match the Cargo package 'internal-foo'"
        );
        assert!(
            !pattern.matches(&npm_pkg),
            "'cargo:internal-*' must NOT match the npm package 'internal-foo'"
        );
    }
}
